CREATE DATABASE IF NOT EXISTS travelmate; USE travelmate;
CREATE TABLE IF NOT EXISTS users(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,email VARCHAR(150) UNIQUE NOT NULL,password VARCHAR(255) NOT NULL,role VARCHAR(20) DEFAULT 'USER',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS cities(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(100) NOT NULL,state VARCHAR(100),country VARCHAR(100) DEFAULT 'India',description TEXT,image_url VARCHAR(500),latitude DECIMAL(10,7),longitude DECIMAL(10,7));
CREATE TABLE IF NOT EXISTS places(id BIGINT PRIMARY KEY AUTO_INCREMENT,city_id BIGINT,name VARCHAR(150) NOT NULL,description TEXT,category VARCHAR(50),entry_fee DECIMAL(10,2),opening_time VARCHAR(20),closing_time VARCHAR(20),latitude DECIMAL(10,7),longitude DECIMAL(10,7),rating DECIMAL(2,1),image_url VARCHAR(500),FOREIGN KEY(city_id) REFERENCES cities(id));
CREATE TABLE IF NOT EXISTS food_places(id BIGINT PRIMARY KEY AUTO_INCREMENT,city_id BIGINT,name VARCHAR(150),description TEXT,food_type VARCHAR(50),price_range VARCHAR(50),address VARCHAR(255),latitude DECIMAL(10,7),longitude DECIMAL(10,7),rating DECIMAL(2,1),image_url VARCHAR(500),FOREIGN KEY(city_id) REFERENCES cities(id));
CREATE TABLE IF NOT EXISTS markets(id BIGINT PRIMARY KEY AUTO_INCREMENT,city_id BIGINT,name VARCHAR(150),description TEXT,famous_for VARCHAR(255),opening_time VARCHAR(20),closing_time VARCHAR(20),latitude DECIMAL(10,7),longitude DECIMAL(10,7),rating DECIMAL(2,1),image_url VARCHAR(500),FOREIGN KEY(city_id) REFERENCES cities(id));
CREATE TABLE IF NOT EXISTS stays(id BIGINT PRIMARY KEY AUTO_INCREMENT,city_id BIGINT,name VARCHAR(150),description TEXT,type VARCHAR(50),price_per_night DECIMAL(10,2),address VARCHAR(255),latitude DECIMAL(10,7),longitude DECIMAL(10,7),rating DECIMAL(2,1),image_url VARCHAR(500),FOREIGN KEY(city_id) REFERENCES cities(id));
CREATE TABLE IF NOT EXISTS trips(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT,city_id BIGINT,trip_name VARCHAR(150),start_date DATE,end_date DATE,budget DECIMAL(10,2),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(city_id) REFERENCES cities(id));
CREATE TABLE IF NOT EXISTS itinerary_items(id BIGINT PRIMARY KEY AUTO_INCREMENT,trip_id BIGINT,place_id BIGINT,visit_date DATE,start_time TIME,end_time TIME,notes TEXT,sequence_no INT,FOREIGN KEY(trip_id) REFERENCES trips(id),FOREIGN KEY(place_id) REFERENCES places(id));
CREATE TABLE IF NOT EXISTS favorites(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT,place_id BIGINT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE(user_id,place_id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(place_id) REFERENCES places(id));
CREATE TABLE IF NOT EXISTS reviews(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT,place_id BIGINT,rating INT,comment TEXT,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(place_id) REFERENCES places(id));
INSERT INTO cities(name,state,country,description,latitude,longitude) SELECT 'Hyderabad','Telangana','India','City of pearls, biryani and historic landmarks.',17.3850,78.4867 WHERE NOT EXISTS (SELECT 1 FROM cities WHERE name='Hyderabad');
INSERT INTO places(city_id,name,description,category,entry_fee,opening_time,closing_time,latitude,longitude,rating) SELECT c.id,'Charminar','Iconic four-minaret monument in the heart of Hyderabad.','HISTORICAL',0,'09:30','17:30',17.3616,78.4747,4.5 FROM cities c WHERE c.name='Hyderabad' AND NOT EXISTS (SELECT 1 FROM places WHERE name='Charminar');
INSERT INTO places(city_id,name,description,category,entry_fee,opening_time,closing_time,latitude,longitude,rating) SELECT c.id,'Golconda Fort','Historic fort complex with panoramic city views.','HISTORICAL',25,'09:00','17:30',17.3833,78.4011,4.6 FROM cities c WHERE c.name='Hyderabad' AND NOT EXISTS (SELECT 1 FROM places WHERE name='Golconda Fort');
INSERT INTO places(city_id,name,description,category,entry_fee,opening_time,closing_time,latitude,longitude,rating) SELECT c.id,'Hussain Sagar','Large lake and popular leisure destination near central Hyderabad.','NATURE',0,'00:00','23:59',17.4239,78.4738,4.3 FROM cities c WHERE c.name='Hyderabad' AND NOT EXISTS (SELECT 1 FROM places WHERE name='Hussain Sagar');
